<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api'
const router=useRouter();const loading=ref(false);const error=ref('');const form=reactive({old_password:'',new_password:'',confirm:''})
async function submit(){error.value='';if(form.new_password.length<12){error.value='新密码至少12位';return}if(form.new_password===form.old_password){error.value='新密码不能与当前密码相同';return}if(form.new_password!==form.confirm){error.value='两次输入的新密码不一致';return}loading.value=true;try{await api('/auth/password/change',{method:'POST',body:JSON.stringify({old_password:form.old_password,new_password:form.new_password})});await router.push('/workbench/A03')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function logout(){localStorage.removeItem('clothp_access_token');localStorage.removeItem('clothp_refresh_token');window.location.href='/login'}
</script>
<template><div class="login-page"><section class="login-hero"><div class="login-logo">一智算 · 账号安全</div><div><h1>首次使用重置密码<br>请先设置新密码</h1><p>新密码设置完成前，系统不会加载任何生产、工资或租户业务数据。其他已登录设备已退出。</p></div></section><section class="login-form-wrap"><form class="login-form" @submit.prevent="submit"><h2>设置新密码</h2><p class="text-muted">至少12位，且不能与临时密码相同</p><div v-if="error" class="notice error" style="margin-top:20px">{{error}}</div><div class="field"><label class="required">当前临时密码</label><input v-model="form.old_password" type="password" autocomplete="current-password"></div><div class="field"><label class="required">新密码</label><input v-model="form.new_password" type="password" autocomplete="new-password"></div><div class="field"><label class="required">确认新密码</label><input v-model="form.confirm" type="password" autocomplete="new-password"></div><button class="button" :disabled="loading">{{loading?'正在保存…':'保存并进入系统'}}</button><button type="button" class="button link" style="margin-top:16px" @click="logout">退出登录</button></form></section></div></template>
